sys_script.script:
try { 
    var r = new sn_ws.RESTMessageV2('x_snc_iplookup.IPInfo', 'GetIPInfo');

    // MODIFICAÇÃO 1: Mudamos de '8.8.8.8' para pegar o campo do formulário atual
    r.setStringParameterNoEscape('ipaddress', current.ip_address);

    var response = r.execute();
    var responseBody = response.getBody();
    var httpStatus = response.getStatusCode();

    // MODIFICAÇÃO 2: Lógica para tratar a resposta e salvar no banco se der sucesso (200)
    if (httpStatus === 200) {
        // Converte o texto da resposta da API em um objeto simulado do JavaScript
        var responseObj = JSON.parse(responseBody);

        // Atribui o valor da propriedade 'city' da API para o campo 'city' da nossa tabela
        current.city = responseObj.city;

        // Força a atualização do registro com o novo valor da cidade
        current.update();
    } else {
        gs.error("A API retornou erro. HTTP Status: " + httpStatus);
    }
}
catch(ex) {
    // MODIFICAÇÃO 3: Ajustado o log do catch para relatar o erro conforme pedido
    var message = ex.message;
    gs.error("Erro capturado na Business Rule: " + message);
}
